  private void info(String heading,String body){LinearLayout card=col();pad(card,17,17);card.setBackground(shape(panel,14,border));card.addView(label(heading,16,ink,true));add(card,label(body,14,muted,false),8);add(page,card,15);}
  private void privacy(){add(page,title("Privacy and data"),0);add(page,label("How Utang handles the records you enter.",14,muted,false),9);info("Operator and contact","CCJNKR Development. Email developmentccjnkr@gmail.com for questions about this app. The developer cannot see records stored only on your phone.");info("What you save","Names, amounts, whether you lent or borrowed, dates, payment history, and optional notes. The app needs these to show your ledger. It stores your light or dark theme preference too. Use nicknames and avoid unnecessary sensitive details.");info("Storage and sharing","Entries stay in this app's private storage on your phone until you remove them, clear the app's data, or uninstall. Utang has no internet permission, accounts, advertising, analytics, or tracking cookies. Android automatic app backup is disabled. Data leaves the app only if you choose Export backup or share an exported file yourself.");info("Backups","An exported JSON backup is readable by anyone who can access that file. Keep it somewhere private. Import replaces your current ledger only after you confirm. Exported copies remain wherever you saved them after local deletion.");info("Your choices","You can edit or delete individual records, export a copy, or delete all local records in Settings. Utang does not contact or notify the people you list. If another person entered your name in their private ledger, ask that person to correct or remove it; CCJNKR Development cannot access it remotely.");add(page,button("Email privacy questions",false,()->emailDeveloper()),17);add(page,button("Open Settings",false,()->{view="settings";draw();}),9);}
  private void terms(){add(page,title("Terms and refunds"),0);info("About the service","CCJNKR Development provides Utang as a personal recordkeeping tool. It does not transfer money, collect debts, contact other people, or verify any amount or payment. Check entries with the people involved before relying on them.");info("Purchases and refunds","This version has no purchases, subscriptions, or payments to the developer. There is nothing to refund through the app.");info("Responsibility","You control what names and notes you enter and whether to export a backup. Keep copies you choose to share secure. This information describes the current app, not a legal guarantee. Questions: developmentccjnkr@gmail.com.");}
  private void settings(){add(page,title("Settings"),0);add(page,label("Your records stay on this phone unless you export them.",13,muted,false),8);LinearLayout theme=col();pad(theme,18,18);theme.setBackground(shape(panel,14,border));theme.addView(label("Appearance",18,ink,true));add(theme,label("Switch between light and dark themes.",13,muted,false),8);add(theme,button(dark?"Use light theme":"Use dark theme",false,()->{dark=!dark;getPreferences(0).edit().putBoolean("dark",dark).apply();draw();}),15);add(page,theme,24);
    LinearLayout backup=col();pad(backup,18,18);backup.setBackground(shape(panel,14,border));backup.addView(label("Your data",18,ink,true));add(backup,label("Export a backup before changing phones or clearing app data. Exported JSON is unencrypted.",13,muted,false),8);add(backup,button("Export backup",false,()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"utang-backup-"+now()+".json");startActivityForResult(i,EXPORT);}),15);add(backup,button("Import backup",false,()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}),8);add(backup,button("Delete all records",false,()->new AlertDialog.Builder(dialogContext()).setTitle("Delete all Utang records?").setMessage("This permanently removes your local ledger and payment history. Export a backup first if you want a copy.").setNegativeButton("Cancel",null).setPositiveButton("Delete all",(x,w)->{ledger=new JSONArray();save();draw();notifyUser("All local records deleted");}).show()),8);add(page,backup,15);}
  @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;try{if(request==EXPORT){JSONObject backup=new JSONObject();backup.put("version",1);backup.put("entries",ledger);try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(backup.toString(2).getBytes("UTF-8"));}notifyUser("Backup exported");}if(request==IMPORT){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(data.getData())){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>5000000)throw new Exception("Backup too large");}}JSONObject backup=new JSONObject(out.toString("UTF-8"));if(backup.optInt("version")!=1||backup.optJSONArray("entries")==null)throw new Exception("Invalid Utang backup");JSONArray next=backup.getJSONArray("entries");validateBackup(next);new AlertDialog.Builder(dialogContext()).setTitle("Replace all records?").setMessage("Import "+next.length()+" records and replace your current data?").setNegativeButton("Cancel",null).setPositiveButton("Import",(x,w)->{ledger=next;save();draw();notifyUser("Backup imported");}).show();}}catch(Exception e){notifyUser("Backup failed: "+e.getMessage());}}
